function logDuration(x){return logItems(x).reduce((s,i)=>s+Number(i.duration||0),0)}function logLoad(x){return logItems(x).reduce((s,i)=>s+Number(i.duration||0)*Number(i.rpe||0),0)}function logRpe(x){const d=logDuration(x);return d?logLoad(x)/d:0}
