function chartAutoX(count){return count>28?2.25:count>18?1.75:count>10?1.25:1}
function chartScale(container,autoX=1){const id=container.id;if(!chartScaleState[id])chartScaleState[id]={x:autoX,y:1,autoX};else chartScaleState[id].autoX=autoX;return chartScaleState[id]}
function scaleButton(axis,dir,label){return `<button type="button" data-scale-axis="${axis}" data-scale-dir="${dir}" aria-label="${axis==='x'?'橫軸':'縱軸'}${dir>0?'放大':'縮小'}">${label}</button>`}
function ensureScaleControls(container,autoX=1){const state=chartScale(container,autoX);let bar=container.previousElementSibling;if(!bar?.classList.contains('chart-scale-bar')){bar=document.createElement('div');bar.className='chart-scale-bar';bar.dataset.scaleTarget=container.id;bar.innerHTML=`<span class="chart-scale-title">圖表縮放</span><div class="chart-axis-control"><b>橫軸</b>${scaleButton('x',-1,'−')}<output data-scale-output="x"></output>${scaleButton('x',1,'＋')}</div><div class="chart-axis-control"><b>縱軸</b>${scaleButton('y',-1,'−')}<output data-scale-output="y"></output>${scaleButton('y',1,'＋')}</div><button type="button" class="chart-scale-reset" data-scale-reset>重設</button><small>手機可在圖表內滑動</small>`;container.before(bar)}updateScaleControls(container,state);applyChartScale(container,state)}
function clearScaleControls(container){if(container.previousElementSibling?.classList.contains('chart-scale-bar'))container.previousElementSibling.remove()}
function updateScaleControls(container,state){const bar=container.previousElementSibling;if(!bar?.classList.contains('chart-scale-bar'))return;['x','y'].forEach(axis=>{bar.querySelector(`[data-scale-output="${axis}"]`).textContent=`${Math.round(state[axis]*100)}%`;bar.querySelector(`[data-scale-axis="${axis}"][data-scale-dir="-1"]`).disabled=state[axis]<=CHART_SCALE_STEPS[0];bar.querySelector(`[data-scale-axis="${axis}"][data-scale-dir="1"]`).disabled=state[axis]>=CHART_SCALE_STEPS.at(-1)})}
function applyChartScale(container,state=chartScale(container)){const svg=container.querySelector('svg');if(!svg)return;const dashboard=container.classList.contains('chart-wrap'),baseHeight=dashboard?240:(matchMedia('(max-width:760px)').matches?220:250),baseMinWidth=dashboard?420:560,width=Math.max(container.clientWidth||baseMinWidth,baseMinWidth)*state.x;svg.style.width=`${width}px`;svg.style.minWidth=`${width}px`;svg.style.maxWidth='none';svg.style.height=`${baseHeight*state.y}px`;svg.style.display='block';container.dataset.xScale=state.x;container.dataset.yScale=state.y}
