function saveRxTemplate(){const record={id:crypto.randomUUID(),athleteId:$('#rxBuilderAthlete').value,date:$('#rxBuilderDate').value,title:$('#rxBuilderTitle').value.trim(),intensity:$('#rxBuilderIntensity').value,goal:$('#rxBuilderGoal').value.trim(),exercises:$('#rxBuilderExercises').value.trim(),note:$('#rxBuilderNote').value.trim(),sport:$('#rxBuilderSport').value,division:$('#rxBuilderDivision').value,category:$('#rxBuilderCategory').value,event:$('#rxBuilderEvent').value,focus:$('#rxBuilderFocus').value,templateStandard:'社會組',done:false};if(!record.athleteId||!record.date||!record.title||!record.goal||!record.exercises)return toast('請完成選手、日期與處方草稿');data.prescriptions.push(record);selected=record.athleteId;localStorage.setItem(KEY,JSON.stringify(data));render();toast(`${athlete(record.athleteId).name} 的處方已建立`)}
