function renderLogTrend(){const metric=$('#logTrendMetric')?.value||'load',range=$('#logTrendRange')?.value||'7',all=data.logs.filter(x=>x.athleteId===selected),custom=range==='custom',box=$('#logCustomRange'),start=$('#logTrendStart'),end=$('#logTrendEnd'),container=$('#logTrendChart');box.hidden=!custom;if(custom&&!start.value){const d=new Date();start.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;end.value=today()}const items=custom?all.filter(x=>(!start.value||x.date>=start.value)&&(!end.value||x.date<=end.value)).sort((a,b)=>a.date.localeCompare(b.date)):withinRange(all,range),map={load:[logLoad,'訓練負荷'],rpe:[logRpe,'平均 RPE'],sleep:[x=>x.sleep,'睡眠'],soreness:[x=>x.soreness,'痠痛'],mood:[x=>x.mood,'心情']},[fn,label]=map[metric];if(custom&&start.value&&end.value&&start.value>end.value){clearScaleControls(container);container.innerHTML='<p class="trend-empty">開始日期不可晚於結束日期。</p>';return}trendSvg(container,items,fn,label)}
function jumpMetrics(sj,cmj){sj=Number(sj);cmj=Number(cmj);if(!(sj>0&&cmj>0))return null;const slowSsc=cmj-sj,ei=slowSsc/sj,eur=cmj/sj;return{sj,cmj,diff:slowSsc,slowSsc,ei,ssc:ei*100,eur}}
