function jumpStatus(pair,drop){if(pair&&drop)return['全部完成','ok'];if(pair)return pair.ei<0?['SJ/CMJ需確認','danger']:['SJ/CMJ完成','ok'];if(drop)return['Drop Jump完成','ok'];return['待完成','pending']}
