function updateJumpRow(row){const val=name=>row.querySelector(`[data-jump-field="${name}"]`).value,pair=jumpMetrics(val('sj'),val('cmj')),drop=dropMetrics(val('flightTime'),val('contactTime')),[label,tone]=jumpStatus(pair,drop);row.querySelector('[data-jump-metric="slowSsc"]').textContent=pair?`${pair.slowSsc>=0?'+':''}${pair.slowSsc.toFixed(1)}`:'—';row.querySelector('[data-jump-metric="ei"]').textContent=pair?`${pair.ei.toFixed(3)} (${pair.ssc.toFixed(1)}%)`:'—';row.querySelector('[data-jump-metric="eur"]').textContent=pair?pair.eur.toFixed(2):'—';row.querySelector('[data-jump-metric="rsi"]').textContent=drop?drop.rsi.toFixed(2):'—';const state=row.querySelector('[data-jump-state]');state.textContent=label;state.className=`jump-state ${tone}`;updateJumpBatchSummary()}
function updateJumpBatchSummary(){const rows=$$('[data-jump-row]'),pairs=[],drops=[];let completed=0,partial=0;rows.forEach(row=>{const val=name=>row.querySelector(`[data-jump-field="${name}"]`).value,pair=jumpMetrics(val('sj'),val('cmj')),drop=dropMetrics(val('flightTime'),val('contactTime')),entered=['sj','cmj','flightTime','contactTime'].filter(name=>val(name)).length;if(pair)pairs.push(pair);if(drop)drops.push(drop);if(pair||drop)completed++;if(entered&&!(pair||drop))partial++});$('#jumpCompletedCount').textContent=completed;$('#jumpProgressLabel').textContent=`/ ${data.athletes.length} 完成`;$('#jumpBatchStatus').textContent=completed?`今日已完成 ${completed} 位${partial?`，另有 ${partial} 位數值未完整`:''}`:'尚未輸入今日數值';if(!completed){$('#jumpTeamSummary').innerHTML='輸入 SJ／CMJ 或 Drop Jump 後即時顯示。';return}const stats=[['已完成',completed+' 位']];if(pairs.length)stats.push(['平均 EI',(avg(pairs.map(x=>x.ei))).toFixed(3)],['平均 EUR',avg(pairs.map(x=>x.eur)).toFixed(2)]);if(drops.length)stats.push(['平均 RSI',avg(drops.map(x=>x.rsi)).toFixed(2)]);$('#jumpTeamSummary').innerHTML=stats.map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}
function saveJumpBatch(){const date=$('#jumpTestDate').value,completed=[];$$('[data-jump-row]').forEach(row=>{const val=name=>row.querySelector(`[data-jump-field="${name}"]`).value,pair=jumpMetrics(val('sj'),val('cmj')),drop=dropMetrics(val('flightTime'),val('contactTime'));if(!pair&&!drop)return;const athleteId=row.dataset.jumpRow,condition=row.querySelector('[data-jump-condition]').value,index=data.pairedJumps.findIndex(x=>x.athleteId===athleteId&&x.date===date),previous=index>=0?data.pairedJumps[index]:{},record={...previous,id:previous.id||crypto.randomUUID(),athleteId,date,condition};if(pair)Object.assign(record,pair);if(drop)Object.assign(record,drop);if(index>=0)data.pairedJumps[index]=record;else data.pairedJumps.push(record);completed.push(record)});if(!completed.length)return toast('請至少完成一組 SJ／CMJ 或 Drop Jump 數值');save();toast(`已儲存 ${completed.length} 位選手的跳躍資料`)}
